const N = SWISS.t.length;
const METHODS = [
  { id: "pca", name: "PCA", note: "PCA looks for the directions of greatest spread. The roll is widest across its spiral, so PCA shows it end-on: a spiral, not a sheet. Colours that are far apart along the sheet sit next to each other on neighbouring turns." },
  { id: "tsne", name: "t-SNE", note: "t-SNE keeps each point’s nearest neighbours close. The colours now run in order along a band, so local structure survived, but the sheet is bent and partly torn, and the overall shape means little." },
  { id: "umap", name: "UMAP", note: "UMAP also keeps neighbours together and here keeps the colour order from start to end. It squeezes the sheet into a thin strip and tears it in one place. Points are packed tightly by design." },
  { id: "isomap", name: "Isomap", note: "Isomap measures distance by hopping between neighbours along the sheet, not through the air. For a shape like this that is exactly right: it unrolls the sheet into a flat strip with the colours in order." },
  { id: "lda", name: "LDA", note: "LDA is supervised: it was told which quarter of the sheet each point belongs to and looks for flat (linear) directions that separate those quarters. No straight line can separate a spiral, so it does little better than PCA." },
];

const hue = (t) => `hsl(${Math.round(10 + t * 270)} 80% 62%)`;
const pt = (arr, i) => [arr[2 * i], arr[2 * i + 1]];

function reducedMotion() {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

// The 12 nearest neighbours of point i in the original 3D data.
function neighbours(i) {
  const x = SWISS.x3;
  const d = [];
  for (let j = 0; j < N; j++) {
    if (j === i) continue;
    const a = x[3 * i] - x[3 * j], b = x[3 * i + 1] - x[3 * j + 1], c = x[3 * i + 2] - x[3 * j + 2];
    d.push([a * a + b * b + c * c, j]);
  }
  return new Set(d.sort((p, q) => p[0] - q[0]).slice(0, 12).map((p) => p[1]));
}

export function SwissRoll() {
  const [angle, setAngle] = useState(35);
  const [method, setMethod] = useState("pca");
  const [sel, setSel] = useState(120);
  const [pos, setPos] = useState(() => SWISS.pca.slice());
  const from = useRef(SWISS.pca.slice());

  const raf = useRef(0);
  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  // Tween the 2D points from where they are to the chosen method's layout (instant with reduced motion).
  function choose(id) {
    setMethod(id);
    cancelAnimationFrame(raf.current);
    const target = SWISS[id], start = from.current;
    if (reducedMotion()) { from.current = target; setPos(target); return; }
    let t0;
    const step = (now) => {
      t0 ??= now;
      const k = Math.min(1, (now - t0) / 700), e = k < 0.5 ? 2 * k * k : 1 - (-2 * k + 2) ** 2 / 2;
      const cur = start.map((v, i) => v + (target[i] - v) * e);
      from.current = cur;
      setPos(cur);
      if (k < 1) raf.current = requestAnimationFrame(step);
    };
    raf.current = requestAnimationFrame(step);
  }

  const near = neighbours(sel);
  const a = (angle * Math.PI) / 180, tilt = 0.35;
  const view = Array.from({ length: N }, (_, i) => {
    const X = SWISS.x3[3 * i], Z = SWISS.x3[3 * i + 1], Y = SWISS.x3[3 * i + 2];
    const sx = X * Math.cos(a) + Z * Math.sin(a), depth = -X * Math.sin(a) + Z * Math.cos(a);
    return [sx, -(Y * Math.cos(tilt) - depth * Math.sin(tilt)), depth, i];
  }).sort((p, q) => q[2] - p[2]);
  const m = METHODS.find((x) => x.id === method);
  const cls = (i) => (i === sel ? s.sel : near.has(i) ? s.near : undefined);

  return (
    <div className={s.roll}>
      <div className={s.panels}>
        <div>
          <p className={s.panelHead}>Original data · 3D</p>
          <svg viewBox="-1.15 -1.15 2.3 2.3" role="img" aria-label="A swiss roll: a sheet of points rolled into a spiral, coloured from red at the centre to purple at the outer edge. Nearer points are drawn brighter.">
            {view.map(([x, y, depth, i]) => (
              <circle key={i} cx={x} cy={y} r={i === sel ? 0.05 : 0.022} fill={hue(SWISS.t[i])} fillOpacity={Math.min(1, 1.05 - 0.3 * (depth + 1))} className={cls(i)} onClick={() => setSel(i)} />
            ))}
          </svg>
          <label className={s.range}>
            <span>Turn</span>
            <input type="range" min="-90" max="90" value={angle} onChange={(e) => setAngle(Number(e.target.value))} aria-label="Rotate the 3D view" />
          </label>
        </div>
        <div>
          <p className={s.panelHead}>{m.name} · 2D</p>
          <svg viewBox="-1.15 -1.15 2.3 2.3" role="img" aria-label={`The same points after ${m.name}. ${m.note}`}>
            {Array.from({ length: N }, (_, i) => {
              const [x, y] = pt(pos, i);
              return <circle key={i} cx={x} cy={-y} r={i === sel ? 0.05 : 0.022} fill={hue(SWISS.t[i])} className={cls(i)} onClick={() => setSel(i)} />;
            })}
          </svg>
          <div className={s.tabs} role="group" aria-label="Choose a method">
            {METHODS.map((x) => (
              <button key={x.id} type="button" aria-pressed={x.id === method} onClick={() => choose(x.id)}>{x.name}</button>
            ))}
          </div>
        </div>
      </div>
      <p className={s.note} aria-live="polite"><strong>{m.name}.</strong> {m.note}</p>
      <p className={s.hint}>Click any point: it and its 12 nearest neighbours in 3D are outlined in white in both views. Do they stay together in 2D?</p>
    </div>
  );
}
